const LEVELS = new Set(['basico','facil','medio','dificil','hard']);
const Q = questions.map((row, i) => ({ id: `Q${String(i+1).padStart(3,'0')}`, difficulty:row[0], zone:row[1], label:row[2], question:row[3], options:row[4], right:row[5], explanation:row[6] }));
for (const q of Q) {
  if (!LEVELS.has(q.difficulty) || q.options.length!==4 || q.right<0 || q.right>3 || !q.question || !q.explanation) throw Error(`Questão inválida: ${q.id}`);
}
module.exports = Q;
